class Add:
 def __call__(self,x,/,y=2,*,z=3): return x+y+z
print(Add()(7),Add()(1,y=3,z=5))

class A:
 def __call__(self,x,/): return x
A()(x=7)

class A:
 def __call__(self,*,x): return x
A()()

class A:
 def __call__(self): return 7
class B(A):
 def __call__(self): return 9
del B.__call__
print(B()())

class A:
 def __call__(self): return [1,2]
print(len(A()()))

class A:
 __call__=len
print(A()([1,2]))

class A:
 @classmethod
 def __call__(cls): return cls.__name__
class B(A): pass
print(A()(),B()())

class Receiver:
 def __init__(self,n): self.n=n
 def run(self): return self.n
class A:
 __call__=Receiver(9).run
print(A()())

class Box:
 def __init__(self,n): self.n=n
class A:
 __call__=Box
b=A()(7)
print(type(b).__name__,b.n)

class A:
 __call__=None
A()()

class A:
 __call__=7
A()()

def run(x): return x+1
class A:
 @property
 def __call__(self): return run
print(A()(6))

events=[]
def run(value):
 events.append('run')
 return value
class A:
 @property
 def __call__(self):
  events.append('bind')
  return run
def owner():
 events.append('owner')
 return A()
def argument():
 events.append('arg')
 return 7
print(owner()(argument()))
print(events[0],events[1],events[2],events[3])

class A:
 __call__=property()
A()()

class A:
 @property
 def __call__(self):
  print('binding')
  raise ValueError('binding')
A()()

class A:
 @property
 def __call__(self): return None
A()()

class D:
 def __get__(self,obj,owner):
  print(owner.__name__)
  def run(x): return obj.n+x
  return run
class A:
 n=2
 __call__=D()
class B(A): pass
print(B()(5))

class D:
 def __get__(self,obj,owner): raise AttributeError('bind')
class A:
 __call__=D()
A()()

class D:
 def __get__(self,obj,owner): return 7
class A:
 __call__=D()
A()()

def run(): return 7
class Getter:
 def __call__(self,descriptor,obj,owner): return run
class D:
 __get__=Getter()
class A:
 __call__=D()
print(A()())

class Router:
 def __call__(self,x): return x+1
class A:
 __call__=Router()
print(A()(6))

class Wrap:
 def __init__(self,fn): self.fn=fn
 def __call__(self,x): return self.fn(x)+1
@Wrap
def doubled(x): return x*2
print(doubled(3))

