class A:
 def __init__(self): self.n=0
 @property
 def __call__(self):
  self.n+=1
  def run(): return self.n
  return run
a=A()
print(a(),a())

class A:
 def __call__(self):
  print('before')
  raise ValueError('call')
A()()

class A:
 def __call__(self):
  try: return 7
  finally: print('cleanup')
print(A()())

class Writer:
 def __call__(self,obj,value):
  obj.saved=value
  return 99
class D:
 __set__=Writer()
class A:
 x=D()
a=A()
a.x=7
print(a.saved)

class Notify:
 def __call__(self,owner,name):
  print(owner.__name__,name)
  return 99
class D:
 __set_name__=Notify()
class A:
 x=D()
print(A.__name__)

class Reader:
 def __call__(self,obj): return obj.n
class A:
 n=7
 x=property(Reader())
print(A().x)

class A:
 __call__=None
class B:
 __call__=7
print(callable(A()),callable(B()))

class D:
 def __get__(self,obj,owner):
  print('never')
  raise ValueError('binding')
class A:
 __call__=D()
print(callable(A()))

class A:
 __call__=property()
print(callable(A()))

class A:
 def run(self): return 7
print(callable(A().run),callable(A.run),callable(A.run.__name__))

